/* yykw0 returns 1 + the index of the keyword in [s, e), or 0 if it is not a keyword. */
static int yykw0(const void* s, const void* e) {
	const unsigned char* t = (const unsigned char*)s;
	const long n = (long)((const unsigned char*)e - t);
	const c2_kw_table_t* kt = &yykw0_table;
	const unsigned char* k;
	uint64_t w0, w1 = 0, k0 = 0, k1 = 0, lo, up, fm, w;
	uint32_t slot, eq, i;
	if (n <= 0 || n > 16) return 0;
	/* level 0: lengths of the keys starting with this byte */
	if (n < 16 && !((kt->eh0[t[0]] >> n) & 1u)) return 0;
	if (n > 8) {
		const unsigned char* b = t + n - 8;
		w0 = (uint64_t)t[0] | (uint64_t)t[1] << 8 | (uint64_t)t[2] << 16 | (uint64_t)t[3] << 24
		    | (uint64_t)t[4] << 32 | (uint64_t)t[5] << 40 | (uint64_t)t[6] << 48 | (uint64_t)t[7] << 56;
		w1 = ((uint64_t)b[0] | (uint64_t)b[1] << 8 | (uint64_t)b[2] << 16 | (uint64_t)b[3] << 24
		    | (uint64_t)b[4] << 32 | (uint64_t)b[5] << 40 | (uint64_t)b[6] << 48
		    | (uint64_t)b[7] << 56) >> (8 * (16 - n));
	} else if (n >= 4) {
		const unsigned char* b = t + n - 4;
		w0 = ((uint64_t)t[0] | (uint64_t)t[1] << 8 | (uint64_t)t[2] << 16 | (uint64_t)t[3] << 24)
		    | ((uint64_t)b[0] | (uint64_t)b[1] << 8 | (uint64_t)b[2] << 16
		    | (uint64_t)b[3] << 24) << (8 * (n - 4));
	} else {
		w0 = (uint64_t)t[0] | (uint64_t)t[n >> 1] << (8 * (n >> 1)) | (uint64_t)t[n - 1] << (8 * (n - 1));
	}
	/* branchless ASCII case folding of 'A'..'Z' (no-op if fold is 0) */
	fm = 0x0101010101010101ull * kt->fold;
	lo = w0 & 0x7F7F7F7F7F7F7F7Full;
	up = (lo + 0x3F3F3F3F3F3F3F3Full) & ~(lo + 0x2525252525252525ull) & ~w0 & 0x8080808080808080ull;
	w0 |= (up >> 2) & fm;
	lo = w1 & 0x7F7F7F7F7F7F7F7Full;
	up = (lo + 0x3F3F3F3F3F3F3F3Full) & ~(lo + 0x2525252525252525ull) & ~w1 & 0x8080808080808080ull;
	w1 |= (up >> 2) & fm;
	/* two-level perfect hash and branchless key comparison */
	w = w0 ^ ((uint64_t)n << 56);
	slot = (uint32_t)(((w * kt->m2) >> 56) ^ kt->disp[(w * kt->m1) >> 58]) & 0xFFu;
	k = kt->key + 16 * slot;
	for (i = 0; i < 8; ++i) {
		k0 |= (uint64_t)k[i] << (8 * i);
		k1 |= (uint64_t)k[i + 8] << (8 * i);
	}
	eq = (uint32_t)(((w0 ^ k0) | (w1 ^ k1)) == 0) & (uint32_t)(kt->len[slot] == n);
	return (int)(kt->tok[slot] & (0u - eq));
}
