typedef int (*lexer_t)(const char**);

static void check(lexer_t lex, const char* str, const int* kinds) {
    const char* cur = str;
    for (size_t j = 0;; ++j) {
        int kind = lex(&cur);
        assert(kind == kinds[j]);
        if (kind == END) break;
    }
}

